def test_test_name_display_with_dot_bracket(testdir):
    testdir.makepyfile(
        """
        import pytest
        @pytest.mark.parametrize("a", ["..["])
        def test_boo(a):
            assert 0
        """
    )
    result = testdir.runpytest("-v")
    # Find the test header line (surrounded by underscores) in the output
    for line in result.outlines:
        if line.startswith('_') and line.endswith('_') and 'test_boo[' in line:
            header = line.strip('_').strip()
            # The expected header should be exactly 'test_boo[..[]'
            assert header == 'test_boo[..[]', f"Expected header 'test_boo[..[]', got '{header}'"
            return
    # If we didn't find the header, fail with a helpful message
    raise AssertionError(f"Could not find test header in output:\\n{result.outlines}")

